<?php
namespace Tests\Feature\Students;
use App\Models\Fee; use App\Models\Invoice; use App\Models\InvoiceItem; use App\Models\StudentServiceSubscription;
class StudentProfileServicesTest extends StudentProfileDashboardTestCase {
 public function test_subscription_snapshots_metadata_and_status_render_without_mutation():void { $fee=Fee::create(['name_ru'=>'Транспорт','category'=>Fee::CATEGORY_TRANSPORT,'amount'=>'1.00','is_active'=>true]); $active=StudentServiceSubscription::create(['enrollment_id'=>$this->enrollment->id,'fee_id'=>$fee->id,'start_date'=>'2026-08-01','status'=>'active','metadata'=>['area'=>'Каусер','route'=>'Маршрут 1','payment_period'=>'monthly']]); $old=StudentServiceSubscription::create(['enrollment_id'=>$this->enrollment->id,'fee_id'=>Fee::create(['name_ru'=>'Питание','category'=>Fee::CATEGORY_FOOD,'amount'=>'1.00','is_active'=>true])->id,'start_date'=>'2026-08-01','status'=>'completed','metadata'=>['meal_plan'=>'Комплексное питание']]); $invoice=Invoice::create(['student_id'=>$this->student->id,'academic_year_id'=>$this->enrollment->academic_year_id,'customer_name'=>$this->student->full_name,'total_amount'=>'1500.00','paid_amount'=>'0','remaining_amount'=>'1500.00','status'=>'unpaid']); InvoiceItem::create(['invoice_id'=>$invoice->id,'fee_id'=>$fee->id,'subscription_id'=>$active->id,'description'=>'Транспорт','amount'=>'1500.00','unit_price'=>'1500.00','quantity'=>1,'paid_amount'=>'0','remaining_amount'=>'1500.00','metadata'=>$active->metadata]); $count=StudentServiceSubscription::count(); $this->actingAs($this->admin)->get(route('dashboard.students.show',$this->student))->assertOk()->assertSee('Транспорт')->assertSee('Каусер')->assertSee('Маршрут 1')->assertSee('1500.00 EGP')->assertSee('Комплексное питание')->assertSee('Завершена'); $this->assertSame($count,StudentServiceSubscription::count()); $this->assertSame('active',$active->fresh()->status); $this->assertSame('completed',$old->fresh()->status); }
}
